#!/usr/bin/env python3
# Audit k_37: two own ways to compute the index of the A-submodule generated by the n rows of an n x n matrix C over A = Z[x]/(Phi_p).
# A matrix is a list of n rows, a row is a list of n entries, an entry is a list of p-1 integers (coefficients of 1, x, ..., x^(p-2)).
#   zmatrix(C):  the (p-1)n x (p-1)n integer matrix whose rows are the coefficient vectors of x^j * (row i), j = 0..p-2.
#                Its rows generate the same lattice as the A-span of the rows of C, so |det| is the index (if it is not 0).
#   nm_crt(C):   Nm(det C) by the Chinese remainder theorem: modulo primes l = 1 mod p (increasing from 2^61; span.py uses primes
#                decreasing from 2^62), det C(w^k) by PARI (matdet of a matrix of Mod), k = 1..p-1.  Bound: Hadamard for zmatrix(C):
#                |Nm(det C)| = |det zmatrix(C)| <= prod over its rows of the Euclidean length (computed as an integer upper bound).
import math
import cypari2
pari=cypari2.Pari(); pari.allocatemem(2*10**9,silent=True)
def need(c,msg):
    if not c: raise SystemExit("AUDIT FAILED: "+str(msg))
def mulx(e,p):                                        # x * e in A; e has length p-1
    top=e[-1]; return [-top]+[e[k-1]-top for k in range(1,p-1)]
def zmatrix(C,p):
    out=[]
    for row in C:
        cur=[list(e) for e in row]
        for j in range(p-1):
            out.append([c for e in cur for c in e])
            cur=[mulx(e,p) for e in cur]
    return out
def hadamard_bound(Z):                                # integer B with |det Z| <= B
    sq=1
    for r in Z: sq*=sum(c*c for c in r)
    return math.isqrt(sq)+1
_aux={}
def aux_primes(p):
    if p not in _aux: _aux[p]=[(2**61//p)*p+1,[]]
    return _aux[p]
def next_aux(p,k):
    st=aux_primes(p)
    while len(st[1])<=k:
        l=st[0]+p
        while not pari.isprime(l): l+=p
        st[0]=l
        w=None
        for a in range(2,1000):
            w=pow(a,(l-1)//p,l)
            if w!=1: break
        need(w!=1 and pow(w,p,l)==1,"root of unity")
        st[1].append((l,w))
    return st[1][k]
_nmdetmod=pari("(E,n,p,l,w)->my(V=matrix(p-1,p-1,d,e,Mod(w,l)^((d-1)*e)),EV=E*V,v=Mod(1,l));for(e=1,p-1,v*=matdet(matrix(n,n,i,j,EV[(i-1)*n+j,e])));lift(v)")
def nm_crt(C,p,bound=None):                           # the evaluation at w^e and the determinants are done inside PARI (function nmdetmod above)
    n=len(C)
    if bound is None: bound=hadamard_bound(zmatrix(C,p))
    E=pari.matrix(n*n,p-1,[c for row in C for ent in row for c in ent])
    mod=1; res=0; k=0
    while mod<=2*bound:
        l,w=next_aux(p,k); k+=1
        v=int(_nmdetmod(E,n,p,l,w))
        res=res+mod*((v-res)*pow(mod,-1,l)%l); mod*=l
    if res>mod//2: res-=mod
    return res,k
def trace_form(row,p): return sum(p*sum(c*c for c in e)-sum(e)**2 for e in row)
if __name__=="__main__":                              # self-test on small random matrices: nm_crt against the determinant of zmatrix (PARI, exact)
    import random
    random.seed(1)
    for p,n in ((3,2),(5,3),(7,4),(37,3),(37,5)):
        for _ in range(4):
            C=[[[random.randint(-3,3) for _ in range(p-1)] for _ in range(n)] for _ in range(n)]
            Z=zmatrix(C,p); dz=int(pari.matrix(len(Z),len(Z),[c for r in Z for c in r]).matdet()); nm,k=nm_crt(C,p)
            need(abs(dz)==abs(nm),"self-test p=%d n=%d: %d vs %d"%(p,n,dz,nm))
    print("nmdet self-test passed: |det zmatrix(C)| = |Nm(det C)| on 20 random matrices")
